drop policy agencyflow_storage_read on storage.objects; create policy agencyflow_storage_read on storage.objects for select to authenticated using(bucket_id='agencyflow-designs' and af_private.project_allowed(af_private.storage_project(name)) and exists(select 1 from public.af_projects p where p.id=af_private.storage_project(storage.objects.name) and p.org_id::text=split_part(storage.objects.name,'/',1)));
